/* ============ H: CHATS, UPDATES; N: NOTIFICATIONS ============ */
const chatAuthor=()=>cur()?.p.actor||'me';
const chatStore=(actor=chatAuthor())=>social(actor);
const lastMsg=(id,actor=chatAuthor())=>{const t=chatStore(actor)?.threads[id];return t?.msgs.at(-1);};
function msgPreview(m){const tx=T(m.text);if(tx||!m.media)return tx;const v=m.media.type==='video';return m.media.mode&&m.media.mode!=='normal'?(v?L('Одноразовое видео','Disappearing video'):L('Одноразовое фото','Disappearing photo')):(v?L('Видео','Video'):L('Фото','Photo'));}
function threadIds(arch,actor=chatAuthor()){const st=chatStore(actor);if(!st)return [];return Object.keys(st.threads).filter(k=>chatReadable(k,actor)&&!isBlocked(k)&&(arch?st.archived.has(k):!st.archived.has(k))).sort((a,b)=>(lastMsg(b,actor)?.t||0)-(lastMsg(a,actor)?.t||0));}
function chatUnread(t){const reader=pairMember(),seen=t.readBy?.[reader];return seen==null?(t.unread||0):t.msgs.filter(m=>!m.me&&m.t>seen).length;}
function chatRow(id,actor='me'){const t=ensureThread(id,actor),m=lastMsg(id,actor),n=chatUnread(t);return `<button class="chat-row ${n?'unread':''}" data-go="H02" data-p='${esc(JSON.stringify({id,actor}))}'>${av(id,'round lg')}<span class="tx"><b>${esc(pname(id))}</b><small>${actor==='couple'?esc(pairName())+' · ':''}${m?esc(msgPreview(m)):L('Напиши первым','Say hi first')}</small></span><span class="side2">${n?`<span class="unr">${n}</span>`:''}<time>${m?F.short(m.t):''}</time></span></button>`;}
SC.H01={root:1,tab:'chats',title:()=>L('Чаты','Chats'),render:p=>{const f=activePair()?(p.kind||'all'):'all',q=(p.q||'').toLowerCase(),owners=(S.pair?.status==='active'||S.pair?.status==='dissolved'?['me','couple']:['me']).filter(a=>f==='all'||f===a);const rows=owners.flatMap(actor=>threadIds(false,actor).filter(id=>!q||pname(id).toLowerCase().includes(q)).map(id=>({id,actor,t:lastMsg(id,actor)?.t||0}))).sort((a,b)=>b.t-a.t);const fresh=owners.filter(actor=>authorAllowed(actor)).flatMap(actor=>social(actor).matches.filter(m=>!social(actor).threads[m.p]?.msgs.length&&!isBlocked(m.p)).map(m=>({...m,actor})));
 return `${bar(L('Чаты','Chats'),{actions:`<button class="ibtn" data-act="chatSearch" aria-label="${L('Поиск по чатам','Search chats')}">${I.search}</button>${bellBtn()}`})}<div class="view"><div class="wrap">${activePair()?seg([['all',L('Все','All')],['me',L('Личные','Personal')],['couple',L('От пары','As a couple')]],f,'chatKind')+(f==='couple'?`<p class="note mt8">${I.couple} ${L(`Здесь вы пишете от имени пары «${esc(pairName())}». Партнёр видит эти чаты.`,`Here you write as the couple “${esc(pairName())}”. Your partner sees these chats.`)}</p>`:''):''}${p.searching?`<input class="inp mt12" id="chatQ" aria-label="${L('Поиск по чатам','Search chats')}" value="${esc(p.q||'')}" data-in="chatQ">`:''}${fresh.length?`<div class="sec">${L('Новые совпадения','New matches')}</div><div class="matches">${fresh.map(m=>`<button data-act="openChat" data-v="${m.p}" data-actor="${m.actor}"><span class="ring2">${av(m.p,'round')}</span><span class="mn">${esc(pname(m.p))}${m.actor==='couple'?' · '+esc(pairName()):''}</span></button>`).join('')}</div>`:''}${rows.map(x=>chatRow(x.id,x.actor)).join('')||empty('chat',L('Пока нет диалогов','No conversations yet'),L('Чат открывается после взаимной симпатии.','A mutual like opens a chat.'))}<button class="btn text" data-go="H05">${L('Архив','Archive')}</button></div></div>`;}};
ACT.chatKind=a=>setP('kind',a.dataset.v);
ACT.hSub=a=>setSub(a.dataset.v);
ACT.toPeople=()=>tab('people',{sub:'discover'});
ACT.chatSearch=()=>{const r=cur();r.p.searching=!r.p.searching;r.p.q='';refresh();$('#chatQ')?.focus();};
IN.chatQ=el=>{cur().p.q=el.value;const pos=el.selectionStart;refresh();const n=$('#chatQ');n.focus();n.setSelectionRange(pos,pos);};
ACT.openUpdate=a=>{const u=S.updates.find(x=>x.id===a.dataset.v);if(!u)return;u.read=true;if(u.e)go('E03',{id:u.e});else go('C03',{id:u.c});};

/* H02 — conversation */

/* Message actions refer to an object in its original thread, never a moving array index. */
function identifyChatMessages(t){t.msgs.forEach((m,i)=>{m.id??='msg_'+i+'_'+Math.random().toString(36).slice(2,9);});}
const chatSender=(m,t)=>m.sender||(m.me?realMembers(t.actor)[0]:realMembers(t.target)[0]);
function chatQuoteText(m){return m.media?(m.media.type==='video'?L('Видео','Video'):L('Фото','Photo')):T(m.text)||L('Сообщение','Message');}
function chatQuote(t,id,preview=false){const m=t.msgs.find(m=>m.id===id);if(!m)return '';return `<${preview?'div':'button'} class="chat-quote" ${preview?'':`data-act="chatJump" data-v="${esc(id)}"`}><b>${esc(pname(chatSender(m,t)))}</b><span>${esc(chatQuoteText(m))}</span></${preview?'div':'button'}>`;}
function chatReplyComposer(t,r){if(!r.chatReplyId)return '';return `<div class="reply-target chat-reply">${chatQuote(t,r.chatReplyId,true)}<button class="ibtn sm" data-act="chatReplyCancel" aria-label="${L('Отменить ответ','Cancel reply')}">${I.close}</button></div>`;}
function chatReadMembers(t,m){const sender=chatSender(m,t);return t.members.filter(id=>id!==sender&&Number.isFinite(t.readBy[id])&&t.readBy[id]>=m.t);}
function chatReceipts(t,m){if(!m.me||m.status)return '';const readers=chatReadMembers(t,m).filter(id=>t.msgs.filter(x=>x.me&&!x.status&&chatSender(x,t)!==id&&x.t<=t.readBy[id]).at(-1)===m);if(!readers.length)return '';return `<button class="msg-readers" data-act="chatReadInfo" data-v="${esc(m.id)}" aria-label="${esc(L('Прочитали: ','Read by: ')+readers.map(pname).join(', '))}">${readers.map(id=>`<span title="${esc(pname(id))}">${av(id,'sm round')}</span>`).join('')}</button>`;}
ACT.chatReadInfo=a=>{const t=chatStore()?.threads[cur().p.id],m=t?.msgs.find(x=>x.id===a.dataset.v);if(!m||!chatReadable(t.target,t.actor)||isBlocked(t.target))return;const readers=chatReadMembers(t,m);sheet(()=>({title:L('Прочитали','Read by'),body:`<div class="card list">${t.members.filter(id=>id!==chatSender(m,t)).map(id=>`<div class="li">${av(id,'sm round')}<span class="tx"><b>${esc(pname(id))}</b><small>${readers.includes(id)?L('Прочитано','Read')+' · '+F.time(t.readBy[id]):L('Ещё не прочитано','Not read yet')}</small></span></div>`).join('')}</div>`}));};
ACT.chatJump=a=>{const el=$$('[data-msg-id]').find(el=>el.dataset.msgId===a.dataset.v);el?.scrollIntoView({block:'center',behavior:'smooth'});};
ACT.chatReplyCancel=()=>{delete cur().chatReplyId;refresh();$('#msgIn')?.focus({preventScroll:true});};
function openMessageMenu(el){if(cur()?.id!=='H02'||modalScope())return;const route=cur(),owner=S,session=S.session,actor=chatAuthor(),t=chatStore()?.threads[route.p.id];const m=t?.msgs.find(x=>x.id===el.dataset.msgId);if(!m||!chatReadable(route.p.id,actor)||isBlocked(route.p.id))return;
 const valid=()=>S===owner&&S.session===session&&cur()===route&&chatStore(actor)?.threads[route.p.id]===t&&chatReadable(route.p.id,actor)&&!isBlocked(route.p.id)&&t.msgs.includes(m);
 const writable=()=>valid()&&!t.ended&&isMatch(route.p.id,actor)&&authorAllowed(actor);if(!writable()&&!(m.me&&T(m.text)))return;
 sheet(()=>({title:L('Сообщение','Message'),body:`<div class="card list">${writable()?linkRow({act:'chatMsgReply',icon:'undo',title:L('Ответить','Reply'),noChev:1}):''}${m.me&&T(m.text)?linkRow({act:'chatMsgCopy',icon:'copy',title:L('Копировать','Copy'),noChev:1}):''}</div>`}),{onClose:()=>{S.ui.messageMenu=null;}});S.ui.messageMenu={t,m,route,valid,writable};}
ACT.chatMsgReply=()=>{const c=S.ui.messageMenu;if(!c?.writable())return;const {route,m}=c;closeSheet(true);route.chatReplyId=m.id;refresh();$('#msgIn')?.focus({preventScroll:true});};
ACT.chatMsgCopy=async()=>{const c=S.ui.messageMenu;if(!c?.valid()||!c.m.me||!T(c.m.text))return;const text=T(c.m.text);closeSheet(true);try{await navigator.clipboard.writeText(text);if(c.valid())toast(L('Текст скопирован','Text copied'),{type:'ok'});}catch{if(c.valid())sheet(()=>({title:L('Скопировать текст','Copy text'),body:`<textarea class="inp" readonly aria-label="${L('Текст сообщения','Message text')}">${esc(text)}</textarea>`}));}};
let messagePress=null,messageClickUntil=0;
function cancelMessagePress(){if(messagePress)clearTimeout(messagePress.timer);messagePress=null;}
document.addEventListener('pointerdown',e=>{cancelMessagePress();const el=e.target.closest?.('[data-msg-id]');if(!el||e.button!==0||e.target.closest('button:not(.mtile),a,input,textarea'))return;const press={x:e.clientX,y:e.clientY,el,route:cur()};press.timer=setTimeout(()=>{if(messagePress!==press||cur()!==press.route||!el.isConnected)return;messageClickUntil=Date.now()+800;cancelMessagePress();openMessageMenu(el);},500);messagePress=press;});
document.addEventListener('pointermove',e=>{if(messagePress&&Math.hypot(e.clientX-messagePress.x,e.clientY-messagePress.y)>10)cancelMessagePress();},{passive:true});
for(const type of ['pointerup','pointercancel','scroll'])document.addEventListener(type,cancelMessagePress,true);
document.addEventListener('click',e=>{if(Date.now()<messageClickUntil&&e.target.closest?.('[data-msg-id]')){e.preventDefault();e.stopImmediatePropagation();}},true);
document.addEventListener('contextmenu',e=>{const el=e.target.closest?.('[data-msg-id]');if(!el)return;e.preventDefault();cancelMessagePress();if(!modalScope())openMessageMenu(el);});
document.addEventListener('keydown',e=>{const el=e.target.closest?.('[data-msg-id]');if(el&&e.target===el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openMessageMenu(el);}});

SC.H02={title:p=>pname(p.id),valid:p=>chatReadable(p.id,p.actor||'me')&&!!PEOPLE[p.id]&&(isMatch(p.id,p.actor||'me')||!!social(p.actor||'me')?.threads[p.id]?.ended)&&!isBlocked(p.id),render:(p,r)=>{const id=p.id;const t=ensureThread(id,p.actor||'me');
 identifyChatMessages(t);t.readBy[pairMember()]=Date.now();if(!t.pair)t.unread=0;
 const ended=t.ended||!isMatch(id)||!authorAllowed(chatAuthor());
 const sh=shared(id);const g=receivedGrant(id);const mine=givenGrant(id);const m=chatStore().matches.find(x=>x.p===id);
 const pills=[`<button class="pill hot" data-go="P05" data-p='${esc(JSON.stringify({id,actor:chatAuthor()}))}'>${ic('spark',13)}${esc(sharedSummary(id))}</button>`,/* V11 (UX-16): one access pill that says who shared with whom */g&&mine?`<button class="pill ok" data-go="P08" data-p='${esc(JSON.stringify({id,actor:chatAuthor()}))}'>${I.unlock}${L('Приватное открыто друг другу','Private parts shared both ways')}</button>`:g?`<button class="pill ok" data-go="P08" data-p='${esc(JSON.stringify({id,actor:chatAuthor()}))}'>${I.unlock}${L(`Тебе открыта приватная часть`,`Their private part is shared with you`)}</button>`:mine?`<button class="pill v" data-go="P07" data-p='${esc(JSON.stringify({tab:'byme'}))}'>${I.eye}${L('Твоя приватная часть открыта','Your private part is shared')}</button>`:`<button class="pill" data-act="reqAccess" data-v="${id}">${I.lock}${L('Приватная часть закрыта','Private part closed')}</button>`].join('');
 let lastDay='';const msgs=t.msgs.map((x,i)=>{const day=F.date(x.t);const sep=day!==lastDay?(lastDay=day,`<div class="daysep">${Date.now()-x.t<DAY&&new Date(x.t).getDate()===new Date().getDate()?L('Сегодня','Today'):day}</div>`):'';
  return sep+`<div data-msg-id="${esc(x.id)}" tabindex="0" aria-haspopup="dialog" aria-label="${esc(L('Действия с сообщением','Message actions'))}" class="msg ${x.me?'me':''} ${x.status||''} ${x.media?'has-media':''}">${realMembers(x.me?t.actor:id).length>1?`<b class="msg-sender">${esc(pname(x.sender||(x.me?'me':realMembers(id)[0])))}</b>`:''}${x.replyTo?chatQuote(t,x.replyTo):''}${x.media?chatMediaHTML(x,i):''}${T(x.text)?`<span class="mtx">${esc(T(x.text))}</span>`:''}${x.me?`<div class="st">${F.time(x.t)}<span aria-label="${x.status==='sending'?L('Отправляется','Sending'):x.status==='failed'?L('Не отправлено','Not sent'):L('Доставлено','Delivered')}">${x.status==='sending'?I.clock:x.status==='failed'?I.alert:I.check}</span></div>`:''}</div>${chatReceipts(t,x)}${x.status==='failed'&&!ended?`<button class="msg-retry" data-act="retryMsg" data-v="${i}">${I.undo}${L('Не отправлено · Повторить','Not sent · Retry')}</button>`:''}`;}).join('');
 const ice=!ended&&!t.msgs.length?`<div class="sec">${L('С чего начать','Conversation starters')}</div><div class="chips">${(sh.match.length?sh.match.slice(0,2).map(tp=>L(`Что привело тебя к интересу «${topic(tp)}»?`,`How did you get into ${topic(tp)}?`)):[]).concat([L('Что тебе сейчас интересно изучить?','What would you like to explore right now?'),L('Как тебе удобнее общаться?','How do you prefer to keep in touch?')]).map(x=>`<button class="chip wrap" data-act="ice">${esc(x)}</button>`).join('')}</div>`:'';
 return `<header class="bar solid"><button class="ibtn ghost" data-back aria-label="${L('Назад','Back')}">${I.back}</button><button class="row grow" style="gap:10px;text-align:left;min-width:0" data-go="P01" data-p='${esc(JSON.stringify({id,actor:chatAuthor()}))}'>${av(id,'sm round '+(person(id).online?'on':''))}<span style="display:grid;min-width:0"><b style="font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(pname(id))}</b><small style="font-size:12px;color:${person(id).online?'var(--mint)':'var(--mute)'}">${t.pair?esc(t.members.map(x=>pname(x)).join(' · ')):esc(presence(id))}</small></span></button><button class="ibtn ghost" data-act="chatMenu" data-v="${id}" aria-label="${L('Информация о диалоге','Conversation details')}">${I.more}</button></header>
 <div class="view nodock ${ended?'':'cta1'}"><div class="wrap"><div class="chat-ctx">${pills}</div>
 <div class="msgs" id="msgs"><div class="msg sys">${m?L(`Взаимная симпатия ${F.rel(m.t)}.`,`Mutual like ${F.rel(m.t)}.`):''}</div>${msgs}${!ended&&S.ui.typing===id?`<div class="typing"><i></i><i></i><i></i></div>`:''}</div>${ice}
 ${ended?`<div class="alert mt16">${I.block}<span><b>${L('Контакт прекращён','Connection ended')}</b>${L('Новые сообщения недоступны. История осталась у тебя.','No new messages. The history stays with you.')}</span></div>`:''}
 </div></div><button class="chat-down ${ended?'low':''}" id="chatDown" data-act="chatDown" aria-label="${L('К последним сообщениям','To latest messages')}">${I.down}<em hidden></em></button>${ended?'':`<div class="inputbar">${chatReplyComposer(t,r)}<button class="ibtn ghost" data-act="attach" aria-label="${L('Вложение','Attach')}">${I.plus}</button><textarea id="msgIn" rows="1" placeholder="${L('Сообщение','Message')}" aria-label="${L('Сообщение','Message')}" title="${L('Enter — отправить, Shift+Enter — новая строка. На телефоне Enter — новая строка.','Enter sends, Shift+Enter adds a line. On phones Enter adds a line.')}" data-in="grow" data-enter="send" enterkeyhint="enter">${esc(r.f.msgIn||'')}</textarea><button class="ibtn send" data-act="send" aria-label="${L('Отправить','Send')}" ${(r.f.msgIn||'').trim()?'':'disabled'}>${I.send}</button></div>`}`;},
 after:(p,r)=>{chatScroll(p,r);renderSide();chatTick();}};
/* chat scroll (owner 15.10): jump to the bottom only when the chat opens or after you send. A new message while you read
   older ones keeps your place: a round «down» button appears with a counter of new messages; near the bottom it just follows. */
function chatScroll(p,r){const v=$('#main .view');if(!v)return;const t=chatStore().threads[p.id];const n=t?.msgs.length||0;const toBottom=()=>{v.scrollTop=v.scrollHeight;r.chatNew=0;};
 if(!r.chatInit||r.chatStick){toBottom();r.chatInit=1;r.chatStick=0;}
 else if(n>(r.chatSeen||0)){if(r.chatNear!==false)toBottom();else r.chatNew=(r.chatNew||0)+(n-(r.chatSeen||0));}
 else if(r.chatNear!==false&&S.ui.typing===p.id)toBottom();
 r.chatSeen=n;
 const btn=$('#chatDown');const sync=()=>{const near=v.scrollHeight-v.scrollTop-v.clientHeight<90;r.chatNear=near;if(near)r.chatNew=0;if(btn){btn.classList.toggle('on',!near);const b=btn.querySelector('em');b.textContent=r.chatNew>99?'99+':String(r.chatNew||'');b.hidden=!r.chatNew;}};
 v.addEventListener('scroll',sync,{passive:true});sync();}
ACT.chatDown=()=>{const v=$('#main .view');if(!v)return;cur().chatNew=0;v.scrollTo({top:v.scrollHeight,behavior:'smooth'});};

ACT.ice=a=>{const el=$('#msgIn');if(!el||!isMatch(cur().p.id)||isBlocked(cur().p.id)||chatStore().threads[cur().p.id]?.ended)return;el.value=a.textContent;IN.grow(el);el.focus();};
ACT.send=()=>{const el=$('#msgIn');if(!el)return;const v=el.value.trim();if(!v)return;if(v.length>2000){toast(L('Слишком длинное сообщение: максимум 2000 символов','Message too long: 2000 characters max'),{type:'err'});return;}
 const id=cur().p.id;const t=chatStore().threads[id];if(!isMatch(id)||isBlocked(id)||t.ended)return;const owner=S,session=S.session,actor=chatAuthor(),store=chatStore(),ticket=authorTicket(chatAuthor());const live=()=>validAuthor(ticket)&&S===owner&&S.session===session&&!isBlocked(id)&&isMatch(id,actor)&&store.threads[id]===t&&!t.ended;const msg={me:1,author:chatAuthor(),sender:pairMember(),replyTo:cur().chatReplyId||null,text:{ru:v,en:v},t:Date.now(),status:'sending'};t.msgs.push(msg);delete cur().chatReplyId;cur().f.msgIn='';cur().chatStick=1;refresh();
 net(400).then(()=>{if(!live())return;msg.status='';socialDelivery(id,'message',String(msg.t),{from:actor});if(cur().id==='H02')chatRefresh();maybePush();
  if(!t.replied&&!t.pair){t.replied=1;setTimeout(()=>{if(!live())return;t.readBy[realMembers(id)[0]]=Date.now();S.ui.typing=id;if(cur().id==='H02'&&cur().p.id===id)chatRefresh();setTimeout(()=>{if(!live())return;S.ui.typing=null;store.archived.delete(id);t.msgs.push({me:0,text:{ru:'Интересный вопрос! Дай подумать пару минут 🙂',en:'Good question! Give me a couple of minutes 🙂'},t:Date.now()});if(cur().id==='H02'&&cur().p.id===id)chatRefresh();else{t.unread=(t.unread||0)+1;renderSide();toast(L(`${pname(id)}: новое сообщение`,`${pname(id)}: new message`),{action:{label:L('Открыть','Open'),fn:()=>openChat(id)}});}},1800);},900);}
 }).catch(()=>{if(!live())return;msg.status='failed';if(cur().id==='H02')chatRefresh();toast(L('Сообщение не отправлено. Текст сохранён','Message not sent. Your text is kept'),{type:'err'});});};
ACT.retryMsg=a=>{const id=cur().p.id;if(!isMatch(id)||isBlocked(id)||chatStore().threads[id]?.ended)return;const owner=S,actor=chatAuthor(),store=chatStore();const t=store.threads[id];const msg=t.msgs[+a.dataset.v];msg.status='sending';refresh();net(400).then(()=>{if(S!==owner||!authorAllowed(actor)||!isMatch(id,actor)||isBlocked(id)||t.ended)return;msg.status='';if(cur().id==='H02'&&cur().p.id===id)chatRefresh();}).catch(()=>{if(S!==owner||isBlocked(id)||t.ended)return;msg.status='failed';refresh();toast(NETFAIL(),{type:'err'});});};
ACT.attach=()=>sheet(()=>({title:L('Отправить фото или видео','Send a photo or video'),body:`<div class="card list">${linkRow({act:'attPick',v:'gallery',icon:'image',tone:'v',title:L('Из галереи','From gallery'),sub:L('Фото или видео, до 1 файла','A photo or video, one file'),noChev:1})}${linkRow({act:'attPick',v:'cam',icon:'camera',title:L('Камера','Camera'),noChev:1})}</div>`}));
ACT.attPick=async a=>{closeSheet(true);const id=cur().p.id,route=cur(),owner=S;if(!isMatch(id)||isBlocked(id)||chatStore().threads[id]?.ended)return;
 const files=await pickLocalMedia(a.dataset.v==='cam'?'image/*':'image/*,video/*',false);if(S!==owner||cur()!==route||!files.length)return;S.ui.cm={id,file:files[0],mode:'normal'};sheet(chatSendSheet,{guard:()=>!!S.ui.cm});};
/* ---------- V10 revision part 7: chat media — blur, view once, timed after first view ---------- */
const CM_TTL={t15:15*60e3,t120:2*3600e3,t1440:24*3600e3};
const CM_MODES=()=>[['normal',L('Обычное','Regular'),L('Остаётся в чате','Stays in the chat')],['once',L('Один просмотр','View once'),L('Открывается один раз, после закрытия исчезает','Opens once and is gone after closing')],['t15',L('15 минут после просмотра','15 minutes after viewing'),L('Отсчёт начнётся, когда собеседник откроет','The countdown starts when they open it')],['t120',L('2 часа после просмотра','2 hours after viewing'),L('Отсчёт начнётся, когда собеседник откроет','The countdown starts when they open it')],['t1440',L('24 часа после просмотра','24 hours after viewing'),L('Отсчёт начнётся, когда собеседник откроет','The countdown starts when they open it')]];
const chatNow=()=>Date.now()+(QA.clockShift||0);
/** one-time / timed media: unopened → open/counting → expired. Regular media never expires. */
function cmView(m,reader=pairMember()){if(!m.recipients?.length)return m;return(m.views??={})[reader]??={openedAt:null,done:false};}
function cmState(m,reader=pairMember()){if(m.mode==='normal')return'normal';const v=cmView(m,reader);if(v.done)return'expired';if(!v.openedAt)return'unopened';if(m.mode==='once')return'open';if(v.openedAt+CM_TTL[m.mode]<=chatNow()){v.done=true;if(!m.recipients||m.recipients.every(id=>m.views?.[id]?.done))m.url=null;return'expired';}return'counting';}
const cmLeft=m=>{const v=cmView(m),ms=Math.max(0,v.openedAt+CM_TTL[m.mode]-chatNow()),min=Math.ceil(ms/60e3);return min>=60?L(`${Math.ceil(min/60)} ч`,`${Math.ceil(min/60)} h`):L(`${min} мин`,`${min} min`);};
const cmModeLabel=m=>m.mode==='once'?L('один просмотр','view once'):m.mode==='normal'?'':L(`исчезнет через ${{t15:'15 мин',t120:'2 ч',t1440:'24 ч'}[m.mode]} после просмотра`,`gone ${{t15:'15 min',t120:'2 h',t1440:'24 h'}[m.mode]} after viewing`);
function chatMediaHTML(x,i){const m=x.media,states=x.me&&m.recipients?.length?m.recipients.map(reader=>cmState(m,reader)):null,st=m.mode==='normal'?'normal':states?(states.every(v=>v==='expired')?'expired':states.some(v=>v==='open')?'open':states.some(v=>v==='counting')?'counting':'unopened'):cmState(m),kind=m.type==='video'?L('Видео','Video'):L('Фото','Photo');
 if(st==='normal'){const hidden=!x.me&&S.me.chatBlur!==false&&!m.revealed;const thumb=m.type==='video'?`<video src="${esc(m.url)}" muted playsinline preload="metadata"></video>`:`<img src="${esc(m.url)}" alt="" draggable="false">`;
  return `<button class="mtile ${hidden?'blur':''}" data-act="chatMedia" data-v="${i}" aria-label="${hidden?L(`${kind} скрыто. Нажми, чтобы посмотреть`,`${kind} hidden. Tap to view`):L(`Открыть: ${kind}`,`Open ${kind}`)}">${thumb}${hidden?`<span class="mcover">${I.eyeoff}<b>${L('Нажми, чтобы посмотреть','Tap to view')}</b></span>`:''}</button>`;}
 let line,sub='',can=false;
 if(x.me){line=`${kind} · ${cmModeLabel(m)}`;sub=st==='unopened'?L('ещё не просмотрено','not viewed yet'):st==='open'?L('открыто сейчас','open now'):st==='counting'?L(`просмотрено · осталось ${cmLeft(m)}`,`viewed · ${cmLeft(m)} left`):L('просмотр закончился, файла больше нет в чате','viewing ended; the file is gone from the chat');}
 else{can=st==='unopened'||st==='counting';line=`${kind} · ${cmModeLabel(m)}`;sub=st==='unopened'?(m.mode==='once'?L('нажми, чтобы открыть — посмотреть можно один раз','tap to open — you can view it once'):L('нажми, чтобы открыть — отсчёт начнётся с этого момента','tap to open — the countdown starts then')):st==='counting'?L(`можно открыть ещё · осталось ${cmLeft(m)}`,`can open again · ${cmLeft(m)} left`):st==='open'?L('открыто','open'):L('просмотр закончился','viewing ended');}
 /* owner 15.10: the media sits blurred (like regular blurred media), words in the centre, and a burning match instead of an icon —
    the stick burns down with the time left; burnt out = charred stick, no picture. Your own media can be opened until it burns out. */
 const mineCan=x.me&&st!=='expired'&&!!m.url;const frac=st==='expired'?0:st==='counting'?Math.max(.08,((cmView(m).openedAt||chatNow())+CM_TTL[m.mode]-chatNow())/CM_TTL[m.mode]):1;
 const bg=st!=='expired'&&m.url?(m.type==='video'?`<video class="eph-bg" src="${esc(m.url)}" muted playsinline preload="metadata"></video>`:`<img class="eph-bg" src="${esc(m.url)}" alt="" draggable="false">`):'<span class="eph-ash"></span>';
 return `<button class="mtile eph2 ${st}" ${can||mineCan?`data-act="chatMedia" data-v="${i}"`:'disabled'} aria-label="${esc(line)}. ${esc(sub)}">${bg}<span class="eph-veil"></span><span class="eph-c">${matchSVG(frac,st!=='expired')}<b>${line}</b><small>${sub}${mineCan?` · ${L('нажми, чтобы проверить','tap to check')}`:''}</small></span></button>`;}
/** a match in the jars' liquid style: the stick length is the time left, the flame flickers and throws sparks */
function matchSVG(frac,lit){const top=12+Math.round((1-frac)*34),uid='m'+Math.random().toString(36).slice(2,7);
 /* burnt out: the stick is tilted, but smoke rises straight up from the charred tip — three soft wisps that drift, sway and fade */
 const a=42*Math.PI/180,tx=+(20+(40-top)*Math.sin(a)).toFixed(1),ty=+(40-(40-top)*Math.cos(a)).toFixed(1);
 const smoke=`<g class="smk" style="transform-origin:${tx}px ${ty}px">${[0,1,2].map(k=>`<path class="w w${k}" d="M${tx} ${ty-2} c ${k%2?3:-3} -5, ${k%2?-4:4} -9, 0 -14 s ${k%2?-3:3} -9, 0 -14" fill="none" stroke="url(#${uid}k)" stroke-width="${2.6-k*.5}" stroke-linecap="round"/>`).join('')}<circle class="ember" cx="${tx}" cy="${ty}" r="1.6" fill="#FF7A3D"/></g>`;
 return `<span class="mmatch ${lit?'lit':'out'}" aria-hidden="true"><svg viewBox="-6 -8 56 70"><defs><linearGradient id="${uid}f" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stop-color="#FF3D61"/><stop offset=".55" stop-color="#FF8A3D"/><stop offset="1" stop-color="#FFD66B"/></linearGradient><linearGradient id="${uid}k" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stop-color="#fff" stop-opacity=".55"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient><linearGradient id="${uid}s" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#F1D3A8"/><stop offset="1" stop-color="#C9A274"/></linearGradient></defs>
 <g transform="rotate(42 20 40)"><rect x="17.5" y="${top}" width="5" height="${60-top}" rx="2.5" fill="url(#${uid}s)"/>${lit?`<rect x="17.5" y="${top}" width="5" height="5" rx="2" fill="#3A2A26"/><ellipse cx="20" cy="${top}" rx="4.6" ry="5.2" fill="#B5233F"/>
 <g transform="rotate(-42 20 ${top})"><g class="fl" style="transform-origin:20px ${top}px"><path d="M20 ${top-24} C 28 ${top-14}, 28 ${top-4}, 20 ${top+1} C 12 ${top-4}, 12 ${top-14}, 20 ${top-24} Z" fill="url(#${uid}f)"/><path class="core" d="M20 ${top-13} C 24 ${top-8}, 24 ${top-3}, 20 ${top} C 16 ${top-3}, 16 ${top-8}, 20 ${top-13} Z" fill="#FFF3C4"/></g>
 <circle class="sp s1" cx="18" cy="${top-20}" r="1.2" fill="#FFD66B"/><circle class="sp s2" cx="23" cy="${top-18}" r="1" fill="#FF8A3D"/></g>`:`<rect x="17.5" y="${top}" width="5" height="9" rx="2.5" fill="#2A1F1C"/>`}</g>${lit?'':smoke}</svg></span>`;}
ACT.chatMedia=a=>{const id=cur().p.id,t=chatStore().threads[id];const x=t?.msgs[+a.dataset.v];if(!x?.media||isBlocked(id))return;const m=x.media;const reader=pairMember();if(t.pair&&!x.me)m.recipients??=realMembers(t.actor);const v=cmView(m,reader),st=cmState(m,reader);
 const ticket=authorTicket(chatAuthor()),actor=chatAuthor(),thread=chatStore().threads[id];const guard=()=>validAuthor(ticket)&&chatReadable(id,actor)&&!isBlocked(id)&&thread?.msgs.includes(x)&&!!m.url&&(m.mode==='normal'||cmState(m,reader)!=='expired');
 if(st==='normal'){if(!x.me&&S.me.chatBlur!==false&&!m.revealed){m.revealed=true;refresh();return;}openViewer([{type:m.type,src:m.url}],0,{guard});return;}
 if(x.me){if(!authorAllowed(chatAuthor())||!m.url)return;openViewer([{type:m.type,src:m.url}],0,{guard});return;}
 if(!authorAllowed(chatAuthor())||!isMatch(id)||!(st==='unopened'||st==='counting')||!m.url)return;
 if(!v.openedAt)v.openedAt=chatNow(); // the first conscious tap starts the timer, never a render
 openViewer([{type:m.type,src:m.url,wm:'@'+(S.me.nick||'')}],0,{guard,label:m.mode==='once'?L('Один просмотр — после закрытия исчезнет','View once — gone after you close it'):L(`Осталось ${cmLeft(m)}`,`${cmLeft(m)} left`),onClose:()=>{if(m.mode==='once'){v.done=true;if(!m.recipients||m.recipients.every(id=>m.views?.[id]?.done))m.url=null;}if(cur()?.id==='H02')chatRefresh();}});};
function chatSendSheet(){const c=S.ui.cm;if(!c)return{title:'',body:''};const kind=c.file.type==='video'?L('Видео','Video'):L('Фото','Photo');
 return{title:L(`Отправить: ${kind.toLowerCase()}`,`Send ${kind.toLowerCase()}`),body:`<div class="cm-prev">${c.file.type==='video'?`<video src="${esc(c.file.url)}" muted playsinline controls preload="metadata"></video>`:`<img src="${esc(c.file.url)}" alt="">`}</div>
 ${grp(L('Как можно смотреть','How it can be viewed'),choices(CM_MODES(),c.mode,'cmMode'))}
 <p class="note">${L('Скриншоты и запись экрана в браузере запретить нельзя. В приложении на телефоне мы попросим систему их скрыть, но полной гарантии нет.','Screenshots and screen recording can’t be blocked in a browser. In the phone app we ask the system to hide them, but there’s no full guarantee.')}</p>`,
 foot:`<button class="btn primary" data-act="cmSend">${I.send}${L('Отправить','Send')}</button>`};}
ACT.cmMode=a=>{S.ui.cm.mode=a.dataset.v;resheet();};
ACT.cmSend=a=>{const c=S.ui.cm;if(!c)return;const id=c.id,t=chatStore().threads[id];if(cur().p.id!==id||!isMatch(id)||isBlocked(id)||t.ended){S.ui.cm=null;closeSheet(true);return;}
 if(c.mode!=='normal'&&person(id).verified!==true){toast(L('Собеседник ещё не подтвердил возраст.','The recipient has not verified their age.'),{type:'warn'});return;}
 if(c.mode!=='normal'&&!needAge(()=>ACT.cmSend(a)))return;
 const owner=S,ticket=authorTicket(chatAuthor());const msg={me:1,author:chatAuthor(),sender:pairMember(),replyTo:cur().chatReplyId||null,text:'',t:Date.now(),status:'sending',media:{type:c.file.type,url:c.file.url,mode:c.mode,recipients:t.pair?realMembers(id):undefined,views:{},openedAt:null,done:false}};S.ui.cm=null;closeSheet(true);t.msgs.push(msg);delete cur().chatReplyId;cur().chatStick=1;refresh();
 net(500).then(()=>{if(!validAuthor(ticket)||!isMatch(id,ticket.id)||t.ended)return;msg.status='';if(cur().id==='H02')chatRefresh();
  // prototype: the other person opens a timed/once media a few seconds later, so the sender's states are visible
  if(!t.pair&&msg.media.mode!=='normal')setTimeout(()=>{if(S!==owner||msg.media.openedAt)return;msg.media.openedAt=chatNow();if(msg.media.mode==='once')setTimeout(()=>{msg.media.done=true;msg.media.url=null;if(cur()?.id==='H02')chatRefresh();},4000);if(cur()?.id==='H02')chatRefresh();},5000);
 }).catch(()=>{if(S!==owner)return;msg.status='failed';if(cur().id==='H02')chatRefresh();toast(L('Не отправлено. Нажми «Повторить»','Not sent. Tap Retry'),{type:'err'});});};
/* update a chat without re-rendering the screen (owner 15.10: no flicker, no broken scroll): only the message list is
   rebuilt in place, the scroll position is kept and the «down» button logic decides whether to follow. Elsewhere: chat list refresh. */
/* swap only the messages that really changed: untouched bubbles (and their images) stay as they are, so nothing blinks */
function morphKids(box,fresh){const a=[...box.childNodes],b=[...fresh.childNodes];b.forEach((n,i)=>{const o=a[i];if(!o)box.appendChild(n);else morphNode(o,n);});a.slice(b.length).forEach(o=>o.remove());}
function morphNode(o,n){if(o.nodeType!==n.nodeType||o.nodeName!==n.nodeName){o.replaceWith(n);return;}
 if(o.nodeType!==1){if(o.nodeValue!==n.nodeValue)o.nodeValue=n.nodeValue;return;}if(o.isEqualNode(n))return;
 [...o.attributes].forEach(x=>{if(!n.hasAttribute(x.name))o.removeAttribute(x.name);});[...n.attributes].forEach(x=>{if(o.getAttribute(x.name)!==x.value)o.setAttribute(x.name,x.value);});morphKids(o,n);}
function chatRefresh(){const r=cur();if(r?.id==='H02'){const box=$('#msgs'),v=$('#main .view');if(!box||!v){refresh();return;}const top=v.scrollTop;const tmp=document.createElement('div');tmp.innerHTML=SC.H02.render(r.p,r);const fresh=tmp.querySelector('#msgs');if(!fresh){refresh();return;}morphKids(box,fresh);v.scrollTop=top;chatScroll(r.p,r);renderSide();chatTick();return;}if(r?.id==='H01')refresh();}
function chatTick(){clearTimeout(S.ui.chatTickT);const r=cur();if(r?.id!=='H02')return;const t=chatStore().threads[r.p.id];if(!t?.msgs.some(x=>x.media&&['counting','open'].includes(cmState(x.media))))return;S.ui.chatTickT=setTimeout(()=>{if(cur()===r)chatRefresh();},20000);}
/* H03/H04 — details, mute, archive, end connection, block */
