const todoCount=()=>todoItems().length;
const inboxKind=x=>x.k?({req:'access',eapp:'events',capp:'groups',pinv:'pair',profile:'pair',joint:x.q?.kind==='grant'?'access':'pair'}[x.k]||'other'):({req:'access',grant:'access',event:'events',evok:'events',evapp:'events',group:'groups',groupok:'groups',like:'likes',match:'matches',reply:'replies',follow:'follows',pair:'pair',postok:'posts'}[x.type]||'other');
const inboxFilterLabels=()=>[['all',L('Все','All')],['access',L('Доступы','Access')],['likes',L('Симпатии','Likes')],['matches',L('Совпадения','Matches')],['replies',L('Ответы','Replies')],['events',L('События','Events')],['groups',L('Сообщества','Communities')],['pair',L('Пара','Couple')],['follows',L('Подписки','Follows')],['posts',L('Публикации','Posts')],['other',L('Другое','Other')]];
const inboxTab=p=>['todo','all'].includes(p.k)?p.k:(p.k==='act'||p.k==='upd')?'all':(todoCount()?'todo':'all');
const inboxFilteredEmpty=()=>empty('filter',L('Таких уведомлений пока нет','No notifications of this type'),'',`<button class="btn text auto" data-act="nFilter" data-v="all">${L('Сбросить фильтр','Reset filter')}</button>`);
function appCardHTML(x){const isE=x.k==='eapp',p=isE?x.x.p:x.q.p,ans=isE?x.x.answer:x.q.answer,what=isE?L('Заявка в событие','Event application'):L('Заявка в сообщество','Community request'),name=isE?T(EV(x.e).title):T(COMMUNITIES[x.c].name);
 const btn=(d,cls,l)=>isE?`<button class="btn md ${cls}" data-act="appDecide" data-e="${x.e}" data-v="${p}" data-d="${d}">${l}</button>`:`<button class="btn md ${cls}" data-act="cRequestDecision" data-c="${x.c}" data-v="${esc(x.q.id)}" data-status="${d}">${l}</button>`;
 return `<div class="card rqcard" style="margin-bottom:10px"><div class="row">${av(p,'')}<button class="grow" style="text-align:left" ${profGo(p)}><b style="font-size:16px">${esc(pname(p))}${person(p).age?', '+person(p).age:''}${nameBadges(person(p))}</b><div class="note">${what} · ${esc(name)}</div></button></div>${T(ans)?`<div class="card flat mt12" style="padding:12px 14px"><div style="white-space:pre-wrap">${esc(T(ans)).slice(0,300)}</div></div>`:''}<div class="row g8 mt12">${btn(isE?'approved':'approved','primary',L('Одобрить','Approve'))}${btn('declined','soft',L('Отклонить','Decline'))}</div></div>`;}
function todoHTML(filter='all'){const all=todoItems(),items=all.filter(x=>filter==='all'||inboxKind(x)===filter);if(!items.length)return all.length?inboxFilteredEmpty():empty('check',L('Всё решено','All caught up'),L('Здесь появятся просьбы открыть приватную часть, согласования партнёра и заявки в твои события и сообщества.','Requests to see your private part, partner approvals and applications to your events and communities appear here.'));
 const reqs=items.filter(x=>x.k==='req'),apps=items.filter(x=>x.k==='eapp'||x.k==='capp'),invs=items.filter(x=>x.k==='pinv'),rest=items.filter(x=>!['req','eapp','capp','pinv'].includes(x.k));
 const row=x=>x.k==='profile'?linkRow({act:'pairReview',icon:'clock',title:L('Партнёр предлагает изменения профиля','Your partner proposed profile changes'),sub:esc(pname(x.q.by))}):`<button class="li" data-act="jointReview" data-v="${esc(x.q.id)}"><span class="ico">${I.clock}</span><span class="tx"><b>${x.q.kind==='grant'?L('Партнёр: приватный доступ','Partner: private access'):L('Партнёр: публикация на подтверждение','Partner: post to approve')}</b><small>${esc(pname(x.q.by))}${x.q.kind==='grant'?'':' · '+esc(T(x.q.draft.text)).slice(0,50)}</small></span>${I.chev}</button>`;
 const inv=x=>`<div class="card rqcard" style="margin-bottom:10px"><div class="row">${av(x.p,'')}<button class="grow" style="text-align:left" ${profGo(x.p)}><b style="font-size:16px">${esc(pname(x.p))}${nameBadges(person(x.p))}</b><div class="note">${L('Приглашает тебя связать профили в пару','Invites you to link profiles as a couple')} · ${F.rel(x.t)}</div></button></div><div class="row g8 mt12"><button class="btn md primary" data-act="pairIncomingAnswer" data-v="yes">${L('Принять','Accept')}</button><button class="btn md soft" data-act="pairIncomingAnswer" data-v="no">${L('Отклонить','Decline')}</button></div></div>`;
 return `${invs.map(inv).join('')}${rest.length?`<div class="card list">${rest.map(row).join('')}</div>`:''}${reqs.length?`${reqs.map(x=>reqCardHTML(x.r,x.a)).join('')}`:''}${apps.length?`${apps.map(appCardHTML).join('')}`:''}`;}
SC.N01={title:()=>L('Уведомления','Notifications'),render:(p)=>{const k=inboxTab(p),filter=inboxFilterLabels().some(([v])=>v===p.nfilter)?p.nfilter:'all';
 const all=currentNotifications().filter(n=>!(n.p&&isBlocked(n.p))),list=all.filter(n=>filter==='all'||inboxKind(n)===filter),kinds=new Set((k==='todo'?todoItems():all).map(inboxKind));
 const neu=list.filter(n=>!n.read),old=list.filter(n=>n.read);
 const row=n=>{const [i,t]=NICO[n.type]||['bell',''];return `<button class="nt ${n.read?'':'unread'}" data-act="openNotif" data-v="${n.id}"><span class="ntw">${n.p?av(n.p,''):`<span class="av" style="position:relative">${plate(n.e?EV(n.e).plate:n.c?COMMUNITIES[n.c].plate:'rose')}</span>`}<span class="ico ${t}">${I[i]}</span></span><span class="tx">${NTXT[n.type](n)}<time>${F.rel(n.t)}</time></span>${n.read?'':'<span class="dotu" aria-label="new"></span>'}</button>`;};
 return `${bar(L('Уведомления','Notifications'),{back:1,sm:1,actions:`<button class="ibtn ghost" data-go="K05" aria-label="${L('Настройки уведомлений','Notification settings')}">${I.gear}</button>`})}<div class="view nodock"><div class="wrap">
 ${seg([['todo',L('Нужно решить','To decide'),todoCount()||''],['all',L('Все уведомления','All notifications')]],k,'nTab','sm')}
 <div class="chips scroll inbox-filters">${inboxFilterLabels().filter(([v])=>v==='all'||v===filter||kinds.has(v)).map(([v,l])=>`<button class="chip ${filter===v?'on':''}" data-act="nFilter" data-v="${v}">${l}</button>`).join('')}</div>
 ${k==='all'&&all.some(n=>!n.read)?`<div class="inbox-tools"><button class="inbox-read-all" data-act="readAll">${L('Прочитать все','Mark all read')}</button></div>`:''}
 ${k==='todo'?todoHTML(filter):list.length?`${neu.length?`<div class="sec" style="margin-top:4px">${L('Новые','New')}</div>${neu.map(row).join('')}`:''}${old.length?`<div class="sec">${L('Ранее','Earlier')}</div>${old.map(row).join('')}`:''}`:all.length?inboxFilteredEmpty():empty('bell',L('Уведомлений нет','No notifications'),L('Здесь появятся симпатии, совпадения, запросы и изменения событий.','Likes, matches, requests and event changes appear here.'))}</div></div>`;}};
ACT.nTab=a=>{if(!['todo','all'].includes(a.dataset.v))return;cur().p.nfilter='all';setP('k',a.dataset.v);};
ACT.nFilter=a=>{if(inboxFilterLabels().some(([v])=>v===a.dataset.v))setP('nfilter',a.dataset.v);};
ACT.readAll=()=>{if(cur().id!=='N01'||inboxTab(cur().p)!=='all')return;currentNotifications().filter(n=>!n.p||!isBlocked(n.p)).forEach(n=>{n.read=true;const u=S.updates.find(x=>x.id===n.id);if(u)u.read=true;});refresh();toast(L('Все прочитаны','All marked as read'),{type:'ok'});};
ACT.openNotif=a=>{const n=currentNotifications().find(x=>x.id===a.dataset.v);if(!n||(n.p&&isBlocked(n.p)))return;n.read=true;const update=S.updates.find(x=>x.id===n.id);if(update)update.read=true;if(n.type==='match'&&n.p){if(isMatch(n.p))return openChat(n.p);return tab('chats',{sub:'chats'});}const [id,p]=n.go||['Q01',{}];if(id==='H01')return tab('chats',p||{sub:'chats'});go(id,p||{});};
/* N02 — ask for push only after a useful action */
function maybePush(){if(S.ui.pushAsked||S.ui.pushAskPending)return;const owner=S,session=S.session,route=cur();S.ui.pushAskPending=1;setTimeout(()=>{if(S!==owner||S.session!==session)return;S.ui.pushAskPending=0;if(cur()!==route||modalScope()||route.f?.msgIn)return;S.ui.pushAsked=1;sheet(()=>({title:L('Не пропустить ответ?','Don’t miss a reply?'),lead:`<span class="ico l">${I.bell}</span>`,body:`<div class="card flat row" style="gap:10px"><img src="${LOGO()}" alt="" style="width:34px"><div class="grow"><b style="font-size:14px">FetUre</b><div class="note">${L('У тебя новое уведомление','You have a new notification')}</div></div></div>`,foot:`<button class="btn primary" data-act="pushOk">${L('Включить уведомления','Turn on notifications')}</button><button class="btn text" data-act="closeSheet">${L('Позже','Later')}</button>`}));},900);}
ACT.pushOk=()=>{closeSheet();toast(L('Уведомления включены','Notifications on'),{type:'ok'});};


